<script setup lang="ts">
import { modeLabels, type ShareSnapshot } from '../../../packages/contracts/src/index.js';
import SharedPhoto from './SharedPhoto.vue';
defineProps<{ snapshot: ShareSnapshot; photoSources?: Record<string, string>; access?: { id: string; credential: string } }>();
</script>
<template><article class="shared-content"><p class="eyebrow">TRAVEL ATLAS · 迹屿</p><h1>{{ snapshot.title }}</h1><p class="muted">{{ snapshot.destinations.join(' / ') }} · {{ snapshot.layer === 'plan' ? '计划安排' : '实际补记' }} · {{ snapshot.days.length }} 天</p><p class="small muted">分享时保存的只读内容，行程编辑不会自动更新此页。{{ snapshot.layer === 'actual' ? '实际补记不等于 GPS 实录。' : '' }}</p><section v-for="(day, index) in snapshot.days" :key="index" class="shared-day"><h2>D{{ index + 1 }} · {{ day.title }}</h2><p v-if="day.area || day.date" class="muted">{{ [day.area, day.date].filter(Boolean).join(' · ') }}</p><p v-if="day.stayName">住宿：{{ day.stayName }}</p><ol class="shared-stops"><li v-for="(stop, stopIndex) in day.stops" :key="stopIndex"><small v-if="stop.arrival" class="muted">{{ modeLabels[stop.arrival] }}</small><h3>{{ stop.label }}</h3><p v-if="stop.region || stop.time" class="muted">{{ [stop.region, stop.time].filter(Boolean).join(' · ') }}</p><p v-if="stop.note" class="shared-text">{{ stop.note }}</p></li></ol><p v-if="!day.stops.length" class="muted">这一天还没有安排地点。</p></section><section v-if="snapshot.note" class="shared-day"><h2>行程备注</h2><p class="shared-text">{{ snapshot.note }}</p></section><section v-for="diary in snapshot.diaries" :key="diary.key" class="shared-day shared-diary"><h2>{{ diary.title }}</h2><p v-if="diary.occurredOn" class="muted">{{ diary.occurredOn }}</p><p class="shared-text">{{ diary.body }}</p><figure v-for="photo in diary.photos" :key="photo.key"><SharedPhoto v-if="access" :share-id="access.id" :credential="access.credential" :photo-key="photo.key" :caption="photo.caption"/><img v-else-if="photoSources?.[photo.key]" :src="photoSources[photo.key]" :alt="photo.caption || '待分享的照片'" loading="lazy" decoding="async"><figcaption v-if="photo.caption">{{ photo.caption }}</figcaption></figure></section></article></template>
